import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String[] sozlar = in.nextLine().trim().split(" +");
        StringBuilder natija = new StringBuilder();
        for (int i = 0; i < sozlar.length; i++) {
            if (i > 0) natija.append('-');
            natija.append(sozlar[i].toUpperCase(Locale.ROOT));
        }
        System.out.println(natija);
    }
}

solution.cpp:
#include <cctype>
#include <iostream>
#include <string>
using namespace std;

string katta(const string& soz) {
    string natija;
    for (char c : soz) natija += char(toupper(static_cast<unsigned char>(c)));
    return natija;
}

int main() {
    string natija;
    string soz;
    while (cin >> soz) {
        if (!natija.empty()) natija += '-';
        natija += katta(soz);
    }
    cout << natija << endl;
    return 0;
}
